  contact_visit_desc: {
    en: "Perched on the historic heights of Antananarivo near the Queen's Palace, our gallery welcomes you to discover our framed fine art prints, hand-woven traditional lamba patterns, and certified Zafimaniry sculptures.",
    fr: "Perchée sur les hauteurs historiques d'Antananarivo, près du Palais de la Reine, notre galerie vous accueille pour découvrir nos tirages d'art encadrés, nos lambas traditionnels tissés main et nos sculptures Zafimaniry certifiées.",
    mg: "Amin'ny havoana manan-tantara ao Antananarivo, akaikin'ny Lapan'ny Mpanjakavavy, dia mandray anao ny galerianay hahafantaranao ny sary kanto voasoritra, ny lamba nentim-paharazana vita tanana, ary ny sary sokitra Zafimaniry voamarina.",
    es: "Ubicada en las alturas históricas de Antananarivo, cerca del Palacio de la Reina, nuestra galería le invita a descubrir nuestras impresiones de arte enmarcadas, los tradicionales lamba tejidos a mano y las esculturas Zafimaniry certificadas.",
    pt: "Situada nas alturas históricas de Antananarivo, perto do Palácio da Rainha, a nossa galeria convida-o a descobrir as nossas impressões de arte emolduradas, os tradicionais lamba tecidos à mão e as esculturas Zafimaniry certificadas.",
    de: "Hoch oben auf den historischen Höhen von Antananarivo, in der Nähe des Königinnenpalastes, lädt unsere Galerie Sie ein, unsere gerahmten Kunstdrucke, handgewebten traditionellen Lamba-Muster und zertifizierten Zafimaniry-Skulpturen zu entdecken.",
    it: "Arroccata sulle storiche alture di Antananarivo, vicino al Palazzo della Regina, la nostra galleria vi accoglie per scoprire le nostre stampe d'arte incorniciate, i tradizionali lamba tessuti a mano e le sculture Zafimaniry certificate.",
    ar: "يقع معرضنا على المرتفعات التاريخية لأنتاناناريفو بالقرب من قصر الملكة، ويرحب بكم لاكتشاف مطبوعاتنا الفنية المؤطرة، وأنماط اللامبا التقليدية المنسوجة يدويًا، ومنحوتات زافيمانيري المعتمدة.",
    zh: "我们的画廊坐落在塔那那利佛历史悠久的山丘上，毗邻王后宫，欢迎您前来欣赏装裱美术印刷品、手工编织的传统兰巴图案以及经认证的扎菲马尼里雕塑。",
    ja: "アンタナナリボの歴史ある高台、女王宮殿の近くに位置するギャラリーで、額装されたアートプリント、手織りの伝統ランバ柄、認定ザフィマニリ彫刻をご覧いただけます。",
  },

