  help_faq_a5: {
    en: "The work's base price is multiplied by the size factor and then by the mounting factor, plus a small surcharge for framed and acrylic mounts. Larger sizes and premium mounts (Dibond, acrylic) increase the price.",
    fr: "Le prix de base de l'œuvre est multiplié par le coefficient de taille, puis par le coefficient d'encadrement, plus une petite majoration pour les cadres et les montages acrylique. Les grandes tailles et les montages premium (Dibond, acrylique) augmentent le prix.",
    mg: "Ny vidiny fototra dia ampitomboina amin'ny anton'ny habe, avy eo amin'ny anton'ny fandrakofana, miampy fanampiana kely ho an'ny sary misy gony sy acrylique. Ny habe lehibe sy ny fandrakofana ambony (Dibond, acrylique) dia mampitombo ny vidiny.",
    es: "El precio base de la obra se multiplica por el factor de tamaño y luego por el factor de montaje, más un pequeño recargo para marcos y montajes acrílicos. Los tamaños más grandes y los montajes premium (Dibond, acrílico) aumentan el precio.",
    pt: "O preço base da obra é multiplicado pelo fator de tamanho e depois pelo fator de moldura, mais um pequeno acréscimo para molduras e montagens acrílicas. Tamanhos maiores e molduras premium (Dibond, acrílico) aumentam o preço.",
    de: "Der Grundpreis des Werks wird mit dem Größenfaktor und anschließend mit dem Rahmungsfaktor multipliziert, plus einem kleinen Aufschlag für gerahmte und Acryl-Montagen. Größere Formate und Premium-Montagen (Dibond, Acryl) erhöhen den Preis.",
    it: "Il prezzo base dell'opera viene moltiplicato per il fattore di dimensione e poi per il fattore di montaggio, più un piccolo sovrapprezzo per montaggi incorniciati e acrilici. Dimensioni maggiori e montaggi premium (Dibond, acrilico) aumentano il prezzo.",
    ar: "يُضرب السعر الأساسي للعمل في عامل الحجم ثم في عامل التركيب، بالإضافة إلى رسوم إضافية بسيطة للتركيبات المؤطرة والأكريليك. الأحجام الأكبر والتركيبات الفاخرة (ديبوند، أكريليك) ترفع السعر.",
    zh: "作品的基础价格乘以尺寸系数，再乘以装裱系数，另加少量画框和亚克力装裱附加费。更大尺寸和高级装裱（迪邦铝板、亚克力）会提高价格。",
    ja: "作品の基本価格にサイズ係数を掛け、さらにマウント係数を掛け、額装・アクリルマウントには少額の追加料金が加わります。大きなサイズやプレミアムマウント（ディボンド、アクリル）ほど価格が上がります。",
  },
