    de: "Drucke in limitierter Auflage werden nach Zahlungsbestätigung produziert und versendet. Kostenloser Versand ab {threshold} €, sonst gilt eine Pauschale von {shipping} €. Lieferzeiten und Sendungsverfolgung werden beim Checkout angegeben.",
    it: "Le stampe in edizione limitata vengono prodotte e spedite dopo la conferma del pagamento. Spedizione gratuita da {threshold} €, altrimenti una tariffa fissa di {shipping} €. Tempi e tracciamento vengono forniti al checkout.",
    ar: "تُنتج المطبوعات المحدودة الإصدار وتُشحن بعد تأكيد الدفع. شحن مجاني من {threshold} يورو، وإلا تُطبق رسوم ثابتة قدرها {shipping} يورو. تُقدم أوقات التسليم والتتبع عند إتمام الشراء.",
    zh: "限量版印刷品在付款确认后生产并发货。满{threshold}欧元免运费，否则统一收取{shipping}欧元。交货时间和跟踪信息在结账时提供。",
    ja: "限定版プリントは、お支払い確認後に製造・発送されます。{threshold}€以上のご注文で送料無料、それ以外は一律{shipping}€が適用されます。納期と追跡情報はチェックアウト時に提供されます。",
