    mg: "Angoninay ny fampahalalana omenao rehefa mamorona kaonty (anarana, mailaka), mibaiko sary (adiresy fandefasana), ary angona ara-teknika toy ny adiresy IP sy ny navigateur mba hiantohana ny fahamarinan'ny sehatra.",
    es: "Recopilamos la información que usted facilita al crear una cuenta (nombre, correo electrónico), al pedir impresiones (dirección de entrega) y datos técnicos como su dirección IP y navegador para garantizar la seguridad y el funcionamiento de la plataforma.",
    pt: "Recolhemos as informações que fornece ao criar uma conta (nome, e-mail), ao encomendar impressões (morada de entrega) e dados técnicos como o seu endereço IP e navegador para garantir a segurança e o funcionamento da plataforma.",
