    fr: "Vos données sont utilisées exclusivement pour fournir nos services : gestion du compte, traitement et livraison des commandes, sécurisation des paiements et support client. Nous ne vendons jamais vos données à des tiers.",
    mg: "Ampiasaina hanomezana ny serivisy anay ihany ny angonao: fitantanana ny kaonty, fanodinana sy fandefasana ny baiko, fiarovana ny fandoavam-bola ary fanohanana mpanjifa. Tsy varotray amin'ny antoko fahatelo mihitsy ny angonao.",
    es: "Sus datos se utilizan exclusivamente para prestar nuestros servicios: gestión de cuentas, procesamiento y entrega de pedidos, seguridad de pagos y atención al cliente. Nunca vendemos sus datos a terceros.",
    pt: "Os seus dados são utilizados exclusivamente para fornecer os nossos serviços: gestão de contas, processamento e entrega de encomendas, segurança de pagamentos e apoio ao cliente. Nunca vendemos os seus dados a terceiros.",
    de: "Ihre Daten werden ausschließlich zur Erbringung unserer Dienste verwendet: Kontoverwaltung, Verarbeitung und Lieferung von Bestellungen, Zahlungssicherheit und Kundensupport. Wir verkaufen Ihre Daten niemals an Dritte.",
    it: "I tuoi dati vengono utilizzati esclusivamente per fornire i nostri servizi: gestione dell'account, elaborazione e consegna degli ordini, sicurezza dei pagamenti e assistenza clienti. Non vendiamo mai i tuoi dati a terzi.",
    ar: "تُستخدم بياناتك حصريًا لتقديم خدماتنا: إدارة الحساب ومعالجة الطلبات وتسليمها وأمن الدفع ودعم العملاء. لا نبيع بياناتك أبدًا لأطراف ثالثة.",
    zh: "您的数据仅用于提供服务：账户管理、订单处理和交付、支付安全以及客户支持。我们绝不会将您的数据出售给第三方。",
