    mg: "Mampiasa cookies sy teknolojia mitovy amin'izany izahay mba hitazomana ny fidiranao, hampahatsiarovana ny safidin'ny fiteny ary handrefesana ny fampiasana tsy misy anarana. Afaka mifehy na mamafa ny cookies amin'ny alalan'ny fandrindrana ny navigateur ianao.",
    es: "Utilizamos cookies y tecnologías similares para mantener su sesión iniciada, recordar su preferencia de idioma y medir el uso anónimo. Puede controlar o eliminar las cookies a través de la configuración de su navegador.",
    pt: "Utilizamos cookies e tecnologias semelhantes para manter a sua sessão iniciada, recordar a sua preferência de idioma e medir a utilização anónima. Pode controlar ou eliminar cookies através das definições do seu navegador.",
