    it: "Utilizziamo cookie e tecnologie simili per mantenere l'accesso, ricordare la preferenza della lingua e misurare l'uso anonimo. Puoi controllare o eliminare i cookie tramite le impostazioni del browser.",
    ar: "نستخدم ملفات تعريف الارتباط وتقنيات مشابهة لإبقائك مسجلًا الدخول وتذكر تفضيل اللغة وقياس الاستخدام المجهول. يمكنك التحكم في ملفات تعريف الارتباط أو حذفها عبر إعدادات المتصفح.",
    zh: "我们使用Cookie和类似技术来保持您的登录状态、记住您的语言偏好并衡量匿名使用情况。您可以通过浏览器设置控制或删除Cookie。",
