  about_manifesto_poem: {
    en: "Every image is a moment stolen from time. Every print, a promise kept · so that the light of Madagascar and Africa shines beyond borders.",
    fr: "Chaque image est un instant volé au temps. Chaque tirage, une promesse tenue · pour que la lumière de Madagascar et d'Afrique rayonne au-delà des frontières.",
    mg: "Ny sary tsirairay dia fotoana nalaina tamin'ny fotoana. Ny tonta tsirairay dia fampanantenana tanteraka · mba hamirapiratan'ny fahazavan'i Madagasikara sy Afrika ankoatran'ny sisintany.",
    es: "Cada imagen es un instante robado al tiempo. Cada impresión, una promesa cumplida · para que la luz de Madagascar y África brille más allá de las fronteras.",
    pt: "Cada imagem é um instante roubado ao tempo. Cada impressão, uma promessa cumprida · para que a luz de Madagáscar e de África brilhe para além das fronteiras.",
    de: "Jedes Bild ist ein dem Moment abgerungenes Zeitfragment. Jeder Druck ein gehaltenes Versprechen · damit das Licht Madagaskars und Afrikas über alle Grenzen leuchtet.",
    it: "Ogni immagine è un istante rubato al tempo. Ogni stampa, una promessa mantenuta · perché la luce del Madagascar e dell'Africa brilli oltre i confini.",
    ar: "كل صورة هي لحظة مختلسة من الزمن. وكل مطبوعة هي وعد محقق · ليتألق ضوء مدغشقر وأفريقيا عبر الحدود.",
    zh: "每一幅图像都是偷自时间的瞬间。每一次印刷，都是恪守的承诺——让马达加斯加与非洲的光芒超越国界闪耀。",
    ja: "すべての写真は時から盗んだ一瞬。すべてのプリントは守られた約束——マダガスカルとアフリカの光が国境を越えて輝くように。",
  },
