export type DictKey = keyof typeof dict;

interface LanguageContextValue {
  lang: LangCode;
  setLang: (lang: LangCode) => void;
  t: (key: DictKey, vars?: Record<string, string>) => string;
}

const LanguageContext = createContext<LanguageContextValue>({
  lang: "en",
  setLang: () => undefined,
  t: (key) => dict[key]?.en ?? String(key),
});

const STORAGE_KEY = "aperio-lang";
const COOKIE_KEY = "aperio-lang";

/* Tiny external store so the language survives a reload (localStorage)
   without ever calling setState synchronously inside an effect. */
const langListeners = new Set<() => void>();

function subscribe(cb: () => void) {
  langListeners.add(cb);
  return () => {
    langListeners.delete(cb);
  };
}

function readStoredLang(): LangCode {
  if (typeof window === "undefined") return "en";
  try {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    if (stored && (SUPPORTED_LANGS as readonly string[]).includes(stored)) return stored as LangCode;
  } catch {
    /* localStorage unavailable — default to English */
  }
  return "en";
}

function readCookieLang(): LangCode {
  if (typeof document === "undefined") return "en";
  try {
    const stored = document.cookie
      .split("; ")
      .find((c) => c.startsWith(`${COOKIE_KEY}=`))
      ?.slice(COOKIE_KEY.length + 1);
    if (stored && (SUPPORTED_LANGS as readonly string[]).includes(stored)) return stored as LangCode;
  } catch {
    /* cookie unavailable — default to English */
  }
  return "en";
}

function writeLangCookie(lang: LangCode) {
  try {
    document.cookie = `${COOKIE_KEY}=${lang}; path=/; max-age=31536000; samesite=Lax`;
  } catch {
    /* cookie write failure — ignore (localStorage still works) */
  }
}

/* The cookie is the authority shared with the server render: it is the only
   source consulted during hydration, so the client always matches the SSR
   output. A legacy localStorage-only language is adopted after mount below. */
function readLang(): LangCode {
  return readCookieLang();
}

function notifyLangListeners() {
  langListeners.forEach((l) => l());
}

export function LanguageProvider({
  children,
  initialLang = "en",
}: {
  children: ReactNode;
  initialLang?: LangCode;
}) {
  /* getServerSnapshot is what the server renders AND what the client hydrates
     against: both must reflect the cookie read server-side (initialLang). */
  const getSnapshot = () => readLang();
  const getServerSnapshot = (): LangCode => initialLang;

  const lang = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);

  // Keep the html lang/dir attributes and the language cookie in sync with the
  // active language (updating an external DOM node is an allowed effect side
  // effect, so the cookie also survives server-side renders on later loads).
  // If no cookie exists yet but a localStorage language was stored before this
  // update, adopt it after mount (no hydration mismatch, since the cookie is
  // the only source consulted during hydration).
  useEffect(() => {
    applyLang(document, lang);
    writeLangCookie(lang);
    const stored = readStoredLang();
    if (readCookieLang() === "en" && stored !== "en") {
      writeLangCookie(stored);
      applyLang(document, stored);
      notifyLangListeners();
    }
  }, [lang]);

  function setLang(next: LangCode) {
    try {
      window.localStorage.setItem(STORAGE_KEY, next);
    } catch {
      /* ignore write errors (private browsing, etc.) */
    }
    writeLangCookie(next);
    notifyLangListeners();
    applyLang(document, next);
  }

  function t(key: DictKey, vars?: Record<string, string>): string {
    let text: string = dict[key]?.[lang] ?? dict[key]?.en ?? String(key);
    if (vars) {
      for (const [k, v] of Object.entries(vars)) text = text.replace(`{${k}}`, v);
    }
    return text;
  }

  return <LanguageContext.Provider value={{ lang, setLang, t }}>{children}</LanguageContext.Provider>;
}

function applyLang(doc: Document, code: LangCode) {
  doc.documentElement.lang = code;
  doc.documentElement.dir = RTL_LANGS.includes(code) ? "rtl" : "ltr";
}

export function useLanguage(): LanguageContextValue {
  return useContext(LanguageContext);
}
